7	/**
8	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
9	 * state recorded in `ServerMod` rows:
10	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
11	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
12	 *
13	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
14	 *
15	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
16	 * mod is installed when nothing was written to their server:
17	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
18	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
19	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
20	 *    FAILED with a clear reason — never silently "INSTALLED".
21	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
22	 *    message. A change we did NOT apply is a failure and must say so.
23	 */
24	
25	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
