35	export async function gameModSync(job: Job): Promise<void> {
36	  const serverId = job.serverId;
37	  if (!serverId) throw new Error("game mod sync: job has no serverId");
38	
39	  const server = await db.server.findUnique({
40	    where: { id: serverId },
41	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true },
42	  });
43	  if (!server) throw new Error(`Server ${serverId} not found`);
44	
45	  const pending = await db.serverMod.findMany({
46	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
47	    include: { mod: true },
48	  });
49	  if (pending.length === 0) return;
50	
51	  const installedNames: string[] = [];
52	  const removedNames: string[] = [];
53	  const failedNames: string[] = [];
54	
55	  for (const sm of pending) {
56	    const removing = sm.status === "REMOVING";
57	    try {
58	      if (SANDBOX) {
59	        // Dev simulation — no VM mutation.
60	        if (removing) {
61	          await db.serverMod.delete({ where: { id: sm.id } });
62	          removedNames.push(sm.mod.name);
63	        } else {
64	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
65	          installedNames.push(sm.mod.name);
66	        }
67	        continue;
68	      }
69	
70	      if (!REAL_ENABLED) {
71	        // Honest failure: nothing was applied. Do NOT report success.
72	        await db.serverMod.update({
73	          where: { id: sm.id },
74	          data: {
75	            status: "FAILED",
76	            error:
77	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
78	          },
79	        });
80	        failedNames.push(sm.mod.name);
81	        continue;
82	      }
83	
84	      // REAL path — install/remove over SSH via the per-source adapter.
85	      const modRow: ModRowFull = {
86	        gameFamily: sm.mod.gameFamily,
87	        source: sm.mod.source,
88	        sourceId: sm.mod.sourceId,
89	        slug: sm.mod.slug,
90	        name: sm.mod.name,
91	        url: sm.mod.url,
92	        variant: server.gameVariant ?? null,
93	        appliesTo: sm.mod.appliesToVariant ?? null,
94	      };
95	      const result = removing ? await removeModReal(server, modRow) : await installModReal(server, modRow);
96	
97	      if (result.ok) {
98	        if (removing) {
99	          await db.serverMod.delete({ where: { id: sm.id } });
100	          removedNames.push(sm.mod.name);
101	        } else {
102	          await db.serverMod.update({
103	            where: { id: sm.id },
104	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
105	          });
106	          installedNames.push(sm.mod.name);
107	        }
108	      } else {
109	        await db.serverMod.update({
110	          where: { id: sm.id },
111	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
112	        });
113	        failedNames.push(sm.mod.name);
114	      }
115	    } catch (e) {
116	      const msg = e instanceof Error ? e.message : String(e);
117	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
118	      await db.serverMod.update({
119	        where: { id: sm.id },
120	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
121	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
122	      });
123	      failedNames.push(sm.mod.name);
124	    }
125	  }
126	
127	  // One summary notification for the batch.
128	  const parts: string[] = [];
129	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
130	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
131	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
132	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
133	  const allFailed = !anyOk && failedNames.length > 0;
134	
135	  await notify(
136	    server.userId,
137	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
138	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
139	    `/dashboard/servers/${server.id}?tab=mods`
140	  );
141	}
