157	type ModResult = { ok: boolean; version?: string; error?: string };
158	type ModRow = {
159	  gameFamily: string;
160	  source: string;
161	  sourceId: string | null;
162	  slug: string;
163	  name: string;
164	  url: string | null;
165	};
