177	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
178	function pascal(name: string): string {
179	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
180	  return p || "Plugin";
181	}
