183	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
184	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip"; file?: string; folder?: string } | null {
185	  switch (mod.source) {
186	    case "modrinth":
187	    case "spigotmc":
188	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
189	    case "umod":
190	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
191	    case "thunderstore":
192	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
193	    default:
194	      return null; // github / nexus / curseforge / codefling / hangar — manual
195	  }
196	}
