198	/** Resolve a direct download URL from the source's API (worker-side). */
199	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
200	  const id = mod.sourceId ?? "";
201	  try {
202	    switch (mod.source) {
203	      case "umod":
204	        return `https://umod.org/plugins/${id}.cs`;
205	      case "spigotmc":
206	        return `https://api.spiget.org/v2/resources/${id}/download`;
207	      case "modrinth": {
208	        const loader = modrinthLoader(mod);
209	        const q = loader ? `?loaders=["${loader}"]` : "";
210	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
211	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
212	        });
213	        if (!res.ok) return null;
214	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
215	        const v = versions[0];
216	        if (!v) return null;
217	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
218	      }
219	      case "thunderstore": {
220	        const [author, ...rest] = id.split("-");
221	        if (!rest.length) return null;
222	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
223	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
224	        });
225	        if (!res.ok) return null;
226	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
227	        return pkg.latest?.download_url ?? null;
228	      }
229	      default:
230	        return null;
231	    }
232	  } catch (e) {
233	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
234	    return null;
235	  }
236	}
