238	function modrinthLoader(mod: ModRowFull): string | null {
239	  // Prefer the mod's own loader target; fall back to the server's variant.
240	  const key = mod.appliesTo ?? mod.variant ?? "";
241	  const map: Record<string, string> = {
242	    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
243	    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
244	  };
245	  return map[key] ?? null;
246	}
