248	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
249	function modDirShell(family: string, variant: string | null): string | null {
250	  switch (family) {
251	    case "minecraft": {
252	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
253	      const sub = modded ? "mods" : "plugins";
254	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
255	    }
256	    case "rust":
257	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
258	    case "valheim":
259	      return `d=$(find /opt /srv /home -maxdepth 9 -type d -name BepInEx 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
260	    default:
261	      return null;
262	  }
263	}
264	
265	const shq = (s: string) => s.replace(/'/g, "'\\''");
