267	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
268	  const target = planTarget(mod);
269	  if (!target) {
270	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
271	  }
272	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
273	  if (!dirShell) {
274	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
275	  }
276	  const url = await resolveUrl(mod);
277	  if (!url) return { ok: false, error: "Could not resolve a download for this mod (it may have moved)." };
278	
279	  let cmd: string;
280	  if (target.kind === "zip") {
281	    cmd =
282	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
283	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
284	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
285	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
286	  } else {
287	    cmd =
288	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
289	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
290	  }
291	
292	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
293	  const s = out.stdout.trim();
294	  if (s.endsWith("OK")) return { ok: true };
295	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
296	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
297	  return { ok: false, error: "Download failed on the server." };
298	}
299	
300	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
301	  const target = planTarget(mod);
302	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
303	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
304	  const rm =
305	    target.kind === "zip"
306	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
307	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
308	  await withSsh(server, (conn) => execRemote(conn, rm));
309	  return { ok: true };
310	}
