312	// --- SSH transport (root@VM, password from the same source as the file manager) ---
313	
314	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
315	
316	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
317	  return new Promise((resolve, reject) => {
318	    const t = connectionTarget(server as any);
319	    if (!t) return reject(new Error("server is not reachable yet"));
320	    const password = serverRootPassword(server as any);
321	    if (!password) return reject(new Error("server has no root password set"));
322	    const conn = new Client();
323	    let settled = false;
324	    const finish = (err: Error | null, val?: T) => {
325	      if (settled) return;
326	      settled = true;
327	      try { conn.end(); } catch { /* best-effort */ }
328	      err ? reject(err) : resolve(val as T);
329	    };
330	    conn.on("ready", () => {
331	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
332	    });
333	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
334	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
335	  });
336	}
337	
338	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
339	  return new Promise((resolve, reject) => {
340	    conn.exec(cmd, (err, stream: ClientChannel) => {
341	      if (err) return reject(err);
342	      let stdout = "";
343	      let stderr = "";
344	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, EXEC_TIMEOUT_MS);
345	      stream
346	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
347	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
348	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
349	    });
350	  });
351	}
